import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private SettingsHolder settingsHolder;

    @Mock
    private Map<String, List<String>> comments;

    public CommentsConfiguration getCommentsConfiguration() {
        return new CommentsConfiguration(comments);
    }

    @Test
    public void newInstanceIsEmpty() {
        CommentsConfiguration instance = new CommentsConfiguration();
        assertTrue(instance.getAllComments().isEmpty());
    }

    @Test
    public void setCommentSetsCommentForPath() {
        CommentsConfiguration instance = getCommentsConfiguration();
        Map<String, List<String>> commentsExpected = Arrays.asList("path", Collections.singletonList(""));
        when(settingsHolder.getComments()).thenReturn(commentsExpected);
        instance.setComment("path", "");
        assertEquals(commentsExpected, instance.getAllComments());
    }

    @Test
    public void setCommentSetsNewLinesForPath() {
        CommentsConfiguration instance = getCommentsConfiguration();
        Map<String, List<String>> commentsExpected = Arrays.asList("path", Collections.singletonList("comment1"), Collections.singletonList(""));
        when(settingsHolder.getComments()).thenReturn(commentsExpected);
        instance.setComment("path", "comment1", "");
        assertEquals(commentsExpected, instance.getAllComments());
    }

    @Test
    public void setCommentSetsNewLinesForMultiplePaths() {
        CommentsConfiguration instance = getCommentsConfiguration();
        Map<String, List<String>> commentsExpected = new HashMap<>();
        commentsExpected.put("path1", Collections.singletonList(""));
        commentsExpected.put("path2", Collections.singletonList("comment2"));
        when(settingsHolder.getComments()).thenReturn(commentsExpected);
        instance.setComment("path1", "", "comment2");
        assertEquals(commentsExpected, instance.getAllComments());
    }

    @Test
    public void setCommentSetsNewLinesForSinglePath() {
        CommentsConfiguration instance = getCommentsConfiguration();
        Map<String, List<String>> commentsExpected = new HashMap<>();
        commentsExpected.put("path", Collections.singletonList(""));
        when(settingsHolder.getComments()).thenReturn(commentsExpected);
        instance.setComment("path", "comment");
        assertEquals(commentsExpected, instance.getAllComments());
    }

    @Test
    public void getCommentsIsUnmodifiable() {
        CommentsConfiguration instance = getCommentsConfiguration();
        Map<String, List<String>> commentsExpected = Collections.emptyMap();
        when(settingsHolder.getComments()).thenReturn(commentsExpected);
        instance.setComment("path", "");
        assertEquals(commentsExpected, instance.getAllComments());
    }
}
